import{_ as a,o as e,c as t,a2 as r}from"./chunks/framework.ClgMjOt7.js";const p=JSON.parse('{"title":"ブックマーク & フォロー管理","description":"公開/非公開ブックマーク、フォロー管理、自動連動処理","frontmatter":{"title":"ブックマーク & フォロー管理","description":"公開/非公開ブックマーク、フォロー管理、自動連動処理"},"headers":[],"relativePath":"features/bookmarks-following.md","filePath":"features/bookmarks-following.md","lastUpdated":1786166106000}'),i={name:"features/bookmarks-following.md"};function l(n,o,s,c,d,k){return e(),t("div",null,[...o[0]||(o[0]=[r('<h1 id="ブックマーク-フォロー管理" tabindex="-1">ブックマーク &amp; フォロー管理 <a class="header-anchor" href="#ブックマーク-フォロー管理" aria-label="Permalink to &quot;ブックマーク &amp; フォロー管理&quot;">​</a></h1><p>作品の保存・管理およびユーザーのフォロー機能についての仕様です。</p><hr><h2 id="ブックマーク機能-bookmarkscreen" tabindex="-1">ブックマーク機能 (<code>BookmarkScreen</code>) <a class="header-anchor" href="#ブックマーク機能-bookmarkscreen" aria-label="Permalink to &quot;ブックマーク機能 (`BookmarkScreen`)&quot;">​</a></h2><ul><li><strong>公開範囲の設定</strong>: <ul><li><code>Restrict.Public</code>: 他ユーザーから閲覧可能な公開ブックマーク</li><li><code>Restrict.Private</code>: 自分のみが閲覧可能な非公開ブックマーク</li><li>追加ボタンの長押しで、公開範囲の選択ダイアログを直接表示可能。</li></ul></li><li><strong>ブックマークタグ分類</strong>: Pixiv のブックマークタグ（追加時付与タグ）に対応。タグごとの絞り込み表示が可能。</li></ul><hr><h2 id="フォロー管理" tabindex="-1">フォロー管理 <a class="header-anchor" href="#フォロー管理" aria-label="Permalink to &quot;フォロー管理&quot;">​</a></h2><ul><li><strong>公開フォロー / 非公開フォロー</strong>: ユーザー詳細画面から、通知が届く「公開フォロー」と通知されない「非公開フォロー」を選択可能。</li><li><strong>フォロー中フィード</strong>: フォロー中ユーザーの最新作品一覧をタイムライン形式で更新表示。</li></ul><hr><h2 id="自動連携フラグ-appsettings" tabindex="-1">自動連携フラグ (<code>AppSettings</code>) <a class="header-anchor" href="#自動連携フラグ-appsettings" aria-label="Permalink to &quot;自動連携フラグ (`AppSettings`)&quot;">​</a></h2><p>設定画面から以下の動作連携を有効化できます。</p><ul><li><code>autoDownloadOnBookmark</code>: 作品をブックマークした際、バックグラウンドでローカルストレージへ原寸保存。</li><li><code>autoBookmarkOnDownload</code>: 作品をローカルへダウンロード保存した際、Pixiv 上のブックマークにも自動追加。</li><li><code>autoTagOnBookmark</code>: ブックマーク追加時に作品に付与されているメインタグを自動設定。</li></ul>',12)])])}const m=a(i,[["render",l]]);export{p as __pageData,m as default};
